practiceProblems.solutionCode:
class Widget {
    int x;

    Widget() {
        this(10);
    }

    Widget(int x) {
        this.x = x;
    }
}

public class Main {
    public static void main(String[] args) {
        Widget w = new Widget();
        System.out.println("Widget value: " + w.x);
    }
}

class Order {
    String item;
    int quantity;

    Order(String item, int quantity) {
        this.item = item;
        if (quantity <= 0) {
            this.quantity = 1;
        } else {
            this.quantity = quantity;
        }
    }

    Order(String item) {
        this(item, 1);
    }
}

public class Main {
    public static void main(String[] args) {
        Order o1 = new Order("Headphones");
        Order o2 = new Order("Screen", -5);
        System.out.println("O1: " + o1.item + " (" + o1.quantity + ") | O2: " + o2.item + " (" + o2.quantity + ")");
    }
}
